"""Persistent shell navigation and playback isolation."""
import json
import shutil
import subprocess
import unittest
from .browser_shell import SHELL_JS

class ShellTests(unittest.TestCase):
    @unittest.skipUnless(shutil.which("node"), "Node required")
    def test_navigation_preserves_views_and_pauses_departing_transport(self):
        script = "const SOURCE=" + json.dumps(SHELL_JS) + ";\n" + "\nconst vm=require('node:vm'),assert=require('node:assert/strict');\nlet hash='',clicks=0;const events={},buttons={},nodes={};\nfunction element(){return {hidden:false,dataset:{},setAttribute(k,v){this[k]=v},removeAttribute(k){delete this[k]},append(){},addEventListener(){}};}\nconst links=['watch','compose','iterations'].map(name=>Object.assign(element(),{dataset:{view:name}}));\nnodes.views={append(){}};nodes.iterations=element();nodes.builds={append(){}};\nconst document={hidden:false,title:'',getElementById:id=>nodes[id],querySelectorAll:()=>links,addEventListener:(n,f)=>events[n]=f,createElement:tag=>{\n const e=element();if(tag==='iframe'){const b={dataset:{state:'playing'},getAttribute:()=> 'Pause playback',click(){clicks++;this.dataset.state='paused';this.getAttribute=()=> 'Play';}};e.contentDocument={getElementById:()=>b,createElement:element,head:{append(){}}};}return e;\n}};\nconst context=vm.createContext({document,location:{hash:'',search:'?seed=7'},addEventListener:(n,f)=>events[n]=f,fetch:()=>Promise.resolve({ok:true,json:()=>Promise.resolve([])})});\nvm.runInContext(SOURCE,context);\nassert.equal(vm.runInContext('frames.size',context),1);\nconst original=vm.runInContext(\"frames.get('watch')\",context);\ncontext.location.hash='#compose';events.hashchange();assert.equal(clicks,1);\nassert.equal(original.hidden,true);\ncontext.location.hash='#watch';events.hashchange();\nassert.equal(vm.runInContext(\"frames.get('watch')\",context),original);\nassert.equal(vm.runInContext('frames.size',context),2);\nassert.equal(clicks,2);\ncontext.location.hash='#iterations';events.hashchange();assert.equal(nodes.iterations.hidden,false);\nassert.equal(vm.runInContext('frames.size',context),2);\ncontext.location.hash='#nonsense';events.hashchange();assert.equal(original.hidden,false);\ndocument.hidden=true;events.visibilitychange();\nassert.equal(links[0]['aria-current'],'page');\nconsole.log('Shell checks passed: lazy mounting, stable view identity, pause on switch, iterations routing, invalid route fallback, current navigation.');\n"
        result = subprocess.run(["node", "-e", script], capture_output=True, text=True, timeout=20)
        self.assertEqual(result.returncode, 0, result.stderr)
